import os
import re
import sys

VALID_METHODS = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
VALID_PERMISSIONS = {'ALLOW', 'DENY'}
VAR_PATTERN = re.compile(r'\{[a-zA-Z0-9_-]+\}')


def normalize_path(path: str) -> str:
    return VAR_PATTERN.sub('{var}', path)


def count_segments(path: str) -> int:
    return len([s for s in path.split('/') if s])


def is_base_match(norm_base: str, norm_path: str) -> bool:
    if norm_base == norm_path:
        return True
    if norm_base == '/':
        return norm_path.startswith('/')
    base_slash = norm_base if norm_base.endswith('/') else norm_base + '/'
    return norm_path.startswith(base_slash)


def is_parent_path(parent_norm: str, child_norm: str) -> bool:
    if parent_norm == child_norm:
        return False
    if parent_norm == '/':
        return True
    p_slash = parent_norm if parent_norm.endswith('/') else parent_norm + '/'
    return child_norm.startswith(p_slash)


class Endpoint:
    def __init__(self, orig_path, method, role, perm, idx):
        self.orig_path = orig_path
        self.norm_path = normalize_path(orig_path)
        self.method = method
        self.role = role
        self.perm = perm
        self.idx = idx
        self.output_path = orig_path


def parse_input(input_path: str):
    if not os.path.exists(input_path):
        return [], None, set(), []

    try:
        with open(input_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception:
        return [], None, set(), []

    lines = content.splitlines()
    idx = 0
    n = len(lines)

    # Skip leading blank lines
    while idx < n and not lines[idx].strip():
        idx += 1

    # Section 1: ENDPOINTS
    raw_endpoints = []
    cutoff_section1 = False
    while idx < n:
        line = lines[idx]
        if not line.strip():
            idx += 1
            break
        if not cutoff_section1:
            parts = line.strip().split()
            if len(parts) != 4:
                cutoff_section1 = True
            else:
                path, method, role, perm = parts
                method_up = method.upper()
                perm_up = perm.upper()
                if (
                    not path
                    or not role
                    or method_up not in VALID_METHODS
                    or perm_up not in VALID_PERMISSIONS
                ):
                    cutoff_section1 = True
                else:
                    raw_endpoints.append((path, method_up, role, perm_up))
        idx += 1

    # Skip blank lines before Section 2
    while idx < n and not lines[idx].strip():
        idx += 1

    # Section 2: BASE/EXCLUDE
    base_path = None
    excluded_roles = set()

    while idx < n:
        line = lines[idx]
        if not line.strip():
            idx += 1
            break
        parts = line.strip().split()
        kw = parts[0].lower() if parts else ''
        if kw in ('base', 'exclude'):
            if kw == 'base' and len(parts) >= 2:
                base_path = parts[1]
            elif kw == 'exclude':
                excluded_roles.update(parts[1:])
            idx += 1
        else:
            # First line that doesn't start with base or exclude -> Section 2 is done!
            break

    # Skip blank lines before Section 3
    while idx < n and not lines[idx].strip():
        idx += 1

    # Section 3: PLAN
    plan_entries = []
    cutoff_section3 = False
    while idx < n:
        line = lines[idx]
        if not line.strip():
            idx += 1
            continue
        if not cutoff_section3:
            parts = line.strip().split()
            if len(parts) != 2:
                cutoff_section3 = True
            else:
                path, method = parts
                method_up = method.upper()
                if not path or method_up not in VALID_METHODS:
                    cutoff_section3 = True
                else:
                    plan_entries.append((path, method_up))
        idx += 1

    return raw_endpoints, base_path, excluded_roles, plan_entries


def canonicalize(raw_endpoints, base_path, excluded_roles, plan_entries):
    if not raw_endpoints:
        return []

    # Map norm_path to the first encountered orig_path (by input order)
    first_orig_path = {}
    for path, method, role, perm in raw_endpoints:
        norm = normalize_path(path)
        if norm not in first_orig_path:
            first_orig_path[norm] = path

    # Build Endpoint objects and deduplicate by (norm_path, method, role)
    seen_tuples = set()
    dedup_endpoints = []
    for idx, (path, method, role, perm) in enumerate(raw_endpoints):
        ep = Endpoint(path, method, role, perm, idx)
        ep.output_path = first_orig_path[ep.norm_path]
        tuple_key = (ep.norm_path, ep.method, ep.role)
        if tuple_key not in seen_tuples:
            seen_tuples.add(tuple_key)
            dedup_endpoints.append(ep)

    # Base path filtering
    norm_base = normalize_path(base_path) if base_path else None
    if norm_base:
        base_endpoints = [
            ep for ep in dedup_endpoints if is_base_match(norm_base, ep.norm_path)
        ]
    else:
        base_endpoints = dedup_endpoints

    if not base_endpoints:
        return []

    # Handle PLAN
    if not plan_entries:
        # Empty PLAN: include all eligible base_endpoints except excluded roles
        result_endpoints = [
            ep for ep in base_endpoints if ep.role not in excluded_roles
        ]
    else:
        plan_norm_tuples = {
            (normalize_path(p_path), p_method) for p_path, p_method in plan_entries
        }
        matched_plan_endpoints = [
            ep
            for ep in base_endpoints
            if (ep.norm_path, ep.method) in plan_norm_tuples
        ]

        direct_plan_eps = [
            ep for ep in matched_plan_endpoints if ep.role not in excluded_roles
        ]

        plan_norm_paths = {ep.norm_path for ep in matched_plan_endpoints}

        endpoints_by_norm_path = {}
        for ep in base_endpoints:
            endpoints_by_norm_path.setdefault(ep.norm_path, []).append(ep)

        all_base_norm_paths = list(endpoints_by_norm_path.keys())
        included_set = set(direct_plan_eps)

        for p_norm_path in plan_norm_paths:
            for candidate_parent_norm in all_base_norm_paths:
                if is_parent_path(candidate_parent_norm, p_norm_path):
                    parent_eps = endpoints_by_norm_path[candidate_parent_norm]
                    non_excluded_parent_eps = [
                        ep for ep in parent_eps if ep.role not in excluded_roles
                    ]

                    if len(non_excluded_parent_eps) > 0:
                        for ep in non_excluded_parent_eps:
                            included_set.add(ep)
                    else:
                        for ep in parent_eps:
                            included_set.add(ep)

        result_endpoints = list(included_set)

    def sort_key(ep):
        segs = count_segments(ep.output_path)
        perm_val = 0 if ep.perm == 'ALLOW' else 1
        return (-segs, ep.output_path, ep.method, ep.role, perm_val)

    result_endpoints.sort(key=sort_key)
    return result_endpoints


def main():
    input_file = '/app/input.txt'
    output_file = '/app/output.txt'

    raw_endpoints, base_path, excluded_roles, plan_entries = parse_input(input_file)
    result_endpoints = canonicalize(raw_endpoints, base_path, excluded_roles, plan_entries)

    os.makedirs(os.path.dirname(output_file), exist_ok=True)
    if not result_endpoints:
        with open(output_file, 'w', encoding='utf-8') as f:
            f.write('\n')
    else:
        with open(output_file, 'w', encoding='utf-8') as f:
            for ep in result_endpoints:
                f.write(f'{ep.output_path} {ep.method} {ep.role} {ep.perm}\n')


